import{_ as n,C as r,o as i,c as s,ah as t,E as o}from"./chunks/framework.sPHStHqt.js";const m=JSON.parse('{"title":"Free Trials","description":"","frontmatter":{},"headers":[],"relativePath":"subscriptions/trials.md","filePath":"subscriptions/trials.md","lastUpdated":1789630599000}'),l={name:"subscriptions/trials.md"};function h(p,e,c,d,u,g){const a=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="free-trials" tabindex="-1">Free Trials <a class="header-anchor" href="#free-trials" aria-label="Permalink to &quot;Free Trials&quot;">​</a></h1><p>A free trial lets a new tenant use their CRM for a set number of days before paying. This page is for the operator: how to turn trials on, how long they last, and what a trial does that a paid plan doesn&#39;t.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>The two things a working trial needs</li><li>How to set the trial length</li><li>What happens when a tenant starts a trial, and when it ends</li></ul></div><h2 id="what-a-trial-is" tabindex="-1">What a trial is <a class="header-anchor" href="#what-a-trial-is" aria-label="Permalink to &quot;What a trial is&quot;">​</a></h2><p>A trial is an ordinary <a href="/subscriptions/plan-management">plan</a> with one switch flipped: <strong>Trial Plan</strong> is turned on. That one change makes the plan <em>granted</em> rather than <em>bought</em> — it has no price, never touches your payment gateway, and runs for a fixed number of days.</p><p>The trial plan still carries real <strong>restrictions</strong> and <strong>permissions</strong>, so a tenant on a trial gets a genuine, if time-limited, version of the product — not a crippled demo.</p><h2 id="turning-trials-on" tabindex="-1">Turning trials on <a class="header-anchor" href="#turning-trials-on" aria-label="Permalink to &quot;Turning trials on&quot;">​</a></h2><p>Two things must both be true before any tenant can start a trial:</p><ol><li><strong>An active plan is marked as the trial plan.</strong> Create a plan, turn on its <strong>Trial Plan</strong> switch, and publish it. Only one trial is offered at a time — if you mark several, the earliest active one is used.</li><li><strong>Trials are enabled in configuration.</strong></li></ol><p>Open <strong>Configuration → Subscription</strong> and find the <strong>Free Trial</strong> group.</p>',10)),o(a,{src:"/images/trials/trial-config.png",alt:"Free Trial configuration"}),e[1]||(e[1]=t('<ul><li><strong>Status</strong> — turn on to offer trials. As the hint says, this <em>&quot;requires an active plan marked as the trial plan&quot;</em> — the switch does nothing on its own.</li><li><strong>Trial Period (Days)</strong> — how many days a trial runs before it expires. Required when Status is on; accepts <strong>1 to 365</strong>, and <strong>defaults to 14</strong> if left unset.</li></ul><p>Save the group. From now on, eligible visitors are offered the trial.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The length is set here, once, for <em>all</em> trials — it isn&#39;t per plan. Change it and every new trial from that point uses the new number; trials already running keep their original end date.</p></div><h2 id="what-the-tenant-experiences" tabindex="-1">What the tenant experiences <a class="header-anchor" href="#what-the-tenant-experiences" aria-label="Permalink to &quot;What the tenant experiences&quot;">​</a></h2><p>When a visitor chooses the trial, Krayin shows a short <strong>confirmation screen</strong> — the plan and the number of days — and, on confirmation, grants it. No card is asked for and nothing is charged.</p><p>The tenant&#39;s CRM is activated immediately and they&#39;re taken straight into it. There is no invoice, because there was no payment — a trial never appears on the <a href="/subscriptions/invoices">Invoices</a> or <a href="/subscriptions/subscribers">Subscribers</a> lists, which track paid subscriptions only.</p><h2 id="one-trial-per-tenant" tabindex="-1">One trial per tenant <a class="header-anchor" href="#one-trial-per-tenant" aria-label="Permalink to &quot;One trial per tenant&quot;">​</a></h2><p>A tenant can take a trial <strong>once</strong>. Once they&#39;ve used it, the trial is no longer offered to that account — they&#39;re asked to choose a paid plan instead. This is enforced at the moment the trial is granted, so re-submitting the form can&#39;t extend a trial that&#39;s already been taken.</p><h2 id="when-a-trial-ends" tabindex="-1">When a trial ends <a class="header-anchor" href="#when-a-trial-ends" aria-label="Permalink to &quot;When a trial ends&quot;">​</a></h2><p>When the trial&#39;s days run out, the tenant&#39;s subscription expires. To keep using their CRM they <a href="/tenants/choosing-a-plan">choose a paid plan</a> and pay for it — at which point they become a subscriber, an invoice is raised, and they appear on the <a href="/subscriptions/subscribers">Subscribers</a> list like any other paying tenant.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Create the plan you&#39;ll mark as the trial → <a href="/subscriptions/plan-management">Plan Management</a></li><li>The full Configuration screen these settings live on → <a href="/settings/configuration">Configuration</a></li><li>How a tenant picks a paid plan after the trial → <a href="/tenants/choosing-a-plan">Choosing a Plan</a></li></ul>',12))])}const b=n(l,[["render",h]]);export{m as __pageData,b as default};
